from pathlib import Path
import argparse,re,json,hashlib
p=argparse.ArgumentParser();p.add_argument('--buddy',required=True);p.add_argument('--output',required=True);a=p.parse_args();source=Path(a.buddy).read_text()
def method(name):
 start=re.search(r'public\s+(?:boolean|void)\s+'+name+r'\(',source).start();first=source.index('{',start);depth=0
 for end in range(first,len(source)):
  if source[end]=='{':depth+=1
  elif source[end]=='}':
   depth-=1
   if depth==0:return source[start:end+1]
 raise ValueError('Original method not closed')
methods=[method('isOldOutstandingMessage'),method('fixupSeenState')]
head='import java.io.*;import java.util.*;import com.biglybt.core.util.*;\nclass ChatMessage {byte[] id;long time;boolean seen;ChatMessage(byte[] id,long time){this.id=id;this.time=time;}byte[] getID(){return id;}long getTimeStamp(){return time;}void setSeen(boolean value){seen=value;}}\nclass BuddyPluginBeta {String info;String getLastMessageInfo(String network,String key){return info;}class Instance {Object chat_lock=new Object();String network="Public",key="Generated read room";List<ChatMessage> messages=new ArrayList<>();ByteArrayHashMap<ChatMessage> message_ids=new ByteArrayHashMap<>();\n'
foot='}}\npublic final class ChatReadMarkerOracle {\n static String text(String hex){char[] chars=new char[hex.length()/4];for(int n=0;n<chars.length;n++)chars[n]=(char)Integer.parseInt(hex.substring(n*4,n*4+4),16);return new String(chars);}\n public static void main(String[] args)throws Exception {try(BufferedReader in=new BufferedReader(new InputStreamReader(System.in,java.nio.charset.StandardCharsets.US_ASCII))){for(String line;(line=in.readLine())!=null;){if(line.equals("D")){StringBuilder result=new StringBuilder();for(int c=0;c<=65535;c++)result.append(Character.forDigit(Character.digit((char)c,10)+1,16));System.out.println(result);continue;}String[] fields=line.split("\\t",-1);BuddyPluginBeta beta=new BuddyPluginBeta();beta.info=fields[0].equals("-")?null:text(fields[0]);BuddyPluginBeta.Instance value=beta.new Instance();for(String record:fields[1].split(",")){String[] parts=record.split(":");ChatMessage msg=new ChatMessage(HexFormat.of().parseHex(parts[0]),Long.parseLong(parts[1]));value.messages.add(msg);value.message_ids.put(msg.id,msg);}List<ChatMessage> targets=new ArrayList<>();for(ChatMessage msg:value.messages){targets.add(msg);targets.add(new ChatMessage(msg.id,msg.time));}StringBuilder result=new StringBuilder();for(ChatMessage msg:targets)result.append(value.isOldOutstandingMessage(msg)?\'1\':\'0\');value.fixupSeenState(targets);result.append(\' \');for(ChatMessage msg:targets)result.append(msg.seen?\'1\':\'0\');System.out.println(result);}}}\n}\n'
out=Path(a.output);out.parent.mkdir(parents=True,exist_ok=True);out.write_text(head+'\n'.join(methods)+foot);(out.parent/'source-scope.json').write_text(json.dumps({'buddy_sha256':hashlib.sha256(source.encode()).hexdigest(),'methods_sha256':[hashlib.sha256(value.encode()).hexdigest() for value in methods],'scope':'exact original old-outstanding/seen-fixup methods; real Base32/ByteArrayHashMap/Java Long and char digit rules; generated ordered object identities and marker; no original UI/profile/network lifecycle'},indent=2)+'\n')
